+function runCommand(command, args, { input = null, timeoutMs = 30000, env = null } = {}) {
+  const result = childProcess.spawnSync(command, args, {
+    encoding: 'utf8',
+    env: env ? { ...process.env, ...env } : process.env,
+    input,
+    maxBuffer: 200 * 1024 * 1024,
+    timeout: timeoutMs,
+  });
+  return {
+    status: result.status ?? (result.error ? 1 : 0),
+    stdout: result.stdout ?? '',
+    stderr: result.stderr ?? '',
+    error: result.error ? result.error.message : null,
+  };
+}
+
+function commandResult(step, commandClass, result, extra = {}) {
+  return {
+    step,
+    command_class: commandClass,
+    exit_code: result.status,
+    stderr_summary: result.error || normalizedString(result.stderr).split(/\r?\n/).filter(Boolean).slice(0, 3).join(' | '),
+    ...extra,
+  };
+}
+
+export function parseSupabaseStatus(stdout) {
+  const jsonMatch = normalizedString(stdout).match(/\{[\s\S]*?\}/);
+  if (!jsonMatch) {
+    return {
+      dbUrl: null,
+      status: {
+        db_url_present: false,
+        stopped_services: [],
+        raw_status_available: false,
+      },
+    };
+  }
+  const parsed = JSON.parse(jsonMatch[0]);
+  const stoppedMatch = normalizedString(stdout).match(/Stopped services:\s*\[([^\]]*)\]/);
+  const stoppedServices = stoppedMatch
+    ? stoppedMatch[1].split(/\s+/).map((item) => item.trim()).filter(Boolean)
+    : [];
+  return {
+    dbUrl: parsed.DB_URL ?? null,
+    status: {
+      db_url_present: Boolean(parsed.DB_URL),
+      stopped_services: stoppedServices,
+      raw_status_available: true,
+    },
+  };
+}
+
+function localDatabaseUrl(rawUrl) {
+  try {
+    const parsed = new URL(rawUrl);
+    return LOCAL_HOSTS.has(parsed.hostname);
+  } catch {
+    return false;
+  }
+}
+
+function databaseUrlForDatabase(rawUrl, databaseName) {
+  const parsed = new URL(rawUrl);
+  parsed.pathname = `/${databaseName}`;
+  return parsed.toString();
+}
+
+function postgresAdminConnection(rawUrl) {
+  const parsed = new URL(rawUrl);
+  const database = parsed.pathname.replace(/^\//, '') || 'postgres';
+  return {
+    host: parsed.hostname,
+    port: parsed.port || '5432',
+    username: parsed.username || 'postgres',
+    password: parsed.password || '',
+    maintenanceDatabase: database,
+  };
+}
+
+function postgresAdminArgs(rawUrl) {
+  const connection = postgresAdminConnection(rawUrl);
+  return [
+    '-h',
+    connection.host,
+    '-p',
+    connection.port,
+    '-U',
+    connection.username,
+    '--maintenance-db',
+    connection.maintenanceDatabase,
+  ];
+}
+
+function postgresAdminEnv(rawUrl) {
+  const connection = postgresAdminConnection(rawUrl);
+  return connection.password ? { PGPASSWORD: connection.password } : {};
+}
+
+export function createdbArgs(rawUrl, databaseName) {
+  return [...postgresAdminArgs(rawUrl), databaseName];
+}
+
+export function dropdbArgs(rawUrl, databaseName) {
+  return ['--if-exists', ...postgresAdminArgs(rawUrl), databaseName];
+}
+
+function sqlLiteral(value) {
+  return `'${normalizedString(value).replace(/'/g, "''")}'`;
+}
+
+function csvCell(value) {
+  return `"${normalizedString(value).replace(/"/g, '""')}"`;
+}
+
+function writeCopyFile(rows, filePath) {
+  const lines = rows.map((row) => {
+    const rowPosture = posture(row);
+    const values = [
+      row.question_key,
+      JSON.stringify(row.question_bank_payload),
+      JSON.stringify(row.analysis_snapshot_payload),
+      JSON.stringify(row.import_receipt_payload),
+      rowPosture.phase_b2_mutation_eligible === true ? 'true' : 'false',
+      row.question_bank_payload.release_scope_status,
+      rowPosture.display_posture,
+      rowPosture.rights_display_status,
+      rowPosture.evidence_availability_status,
+      rowPosture.method_diagnostic_posture,
+      JSON.stringify(sourceRefs(row)),
+      JSON.stringify(blockers(row)),
+      rowHash({
+        question_bank_payload: row.question_bank_payload,
+        analysis_snapshot_payload: row.analysis_snapshot_payload,
+        import_receipt_payload: row.import_receipt_payload,
+      }),
+    ];
+    return values.map(csvCell).join('\t');
+  });
+  fs.writeFileSync(filePath, `${lines.join('\n')}\n`, 'utf8');
+}
